import { Group, Mesh, MeshStandardNodeMaterial, BoxGeometry, CylinderGeometry, SphereGeometry, PlaneGeometry, Vector3, Color } from 'three/webgpu';
import { uniform, time, vec3, mix, smoothstep, positionWorld, normalWorld, cameraPosition, dot, normalize, reflect, pow, max, add, mul, sub, div, length, abs, sin, cos, clamp, step, texture, uv, vec2, vec4, color, timerLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const { ink, paper, accent, surface } = config.intent?.visualSpec?.colors || {};
  const c = { ink: ink || '#16161d', paper: paper || '#e8ecf2', accent: accent || '#ff2a38', surface: surface || '#0b0b10' };

  // --- Load GLB mesh ---
  const meshGroup = new Group();
  group.add(meshGroup);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      meshGroup.add(gltf.scene);
      // Apply PBR material adjustments for machined-metal look
      gltf.scene.traverse((child) => {
        if (child.isMesh) {
          const mat = child.material;
          if (mat) {
            mat.roughness = 0.55;
            mat.metalness = 0.5;
            mat.clearcoat = 0.2;
            mat.clearcoatRoughness = 0.3;
            mat.envMapIntensity = 1.2;
            mat.needsUpdate = true;
          }
        }
      });
    });
  }

  // --- Backdrop capsule shape ---
  const capsuleGroup = new Group();
  group.add(capsuleGroup);

  // Main capsule body
  const bodyGeo = new CylinderGeometry(0.35, 0.35, 0.7, 16, 1, true);
  const bodyMat = new MeshStandardNodeMaterial();
  bodyMat.color = new Color(c.surface);
  bodyMat.roughness = 0.6;
  bodyMat.metalness = 0.45;
  bodyMat.clearcoat = 0.2;
  bodyMat.clearcoatRoughness = 0.3;
  bodyMat.side = ctx.THREE.DoubleSide;

  const bodyMesh = new Mesh(bodyGeo, bodyMat);
  bodyMesh.rotation.x = Math.PI / 2;
  capsuleGroup.add(bodyMesh);

  // End caps
  const capGeo = new SphereGeometry(0.35, 12, 8);
  const capMat = bodyMat.clone();

  const leftCap = new Mesh(capGeo, capMat);
  leftCap.position.x = -0.35;
  leftCap.scale.set(1, 1, 0.3);
  capsuleGroup.add(leftCap);

  const rightCap = new Mesh(capGeo, capMat);
  rightCap.position.x = 0.35;
  rightCap.scale.set(1, 1, 0.3);
  capsuleGroup.add(rightCap);

  // --- Accent rim light strip ---
  const rimGeo = new CylinderGeometry(0.36, 0.36, 0.72, 16, 1, true);
  const rimMat = new MeshStandardNodeMaterial();
  rimMat.color = new Color(c.accent);
  rimMat.emissive = new Color(c.accent);
  rimMat.emissiveIntensity = 0.6;
  rimMat.roughness = 0.3;
  rimMat.metalness = 0.0;
  rimMat.transparent = true;
  rimMat.opacity = 0.3;
  rimMat.side = ctx.THREE.DoubleSide;

  const rimMesh = new Mesh(rimGeo, rimMat);
  rimMesh.rotation.x = Math.PI / 2;
  rimMesh.scale.set(1.02, 1.02, 1.02);
  capsuleGroup.add(rimMesh);

  // --- Edge light accent strip ---
  const stripGeo = new BoxGeometry(0.72, 0.02, 0.02);
  const stripMat = new MeshStandardNodeMaterial();
  stripMat.color = new Color(c.accent);
  stripMat.emissive = new Color(c.accent);
  stripMat.emissiveIntensity = 1.8;
  stripMat.roughness = 0.2;
  stripMat.metalness = 0.0;

  const topStrip = new Mesh(stripGeo, stripMat);
  topStrip.position.y = 0.35;
  capsuleGroup.add(topStrip);

  const bottomStrip = new Mesh(stripGeo, stripMat);
  bottomStrip.position.y = -0.35;
  capsuleGroup.add(bottomStrip);

  // --- Contact shadow plane ---
  const shadowGeo = new PlaneGeometry(1.2, 0.8);
  const shadowMat = new MeshStandardNodeMaterial();
  shadowMat.color = new Color(0x000000);
  shadowMat.transparent = true;
  shadowMat.opacity = 0.4;
  shadowMat.roughness = 1.0;
  shadowMat.metalness = 0.0;
  shadowMat.side = ctx.THREE.DoubleSide;

  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.z = -0.01;
  shadowPlane.rotation.x = -Math.PI / 2;
  capsuleGroup.add(shadowPlane);

  // --- Weighted-settle entrance animation ---
  const tl = gsap.timeline({ paused: true });
  capsuleGroup.scale.set(0, 0, 0);
  tl.to(capsuleGroup.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.7,
    ease: 'power3.out',
    onComplete: () => {
      gsap.to(capsuleGroup.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.9,
        ease: 'power4.out'
      });
    }
  });
  tl.play();

  // --- Hover interaction ---
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(capsuleGroup.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power2.out'
  });

  group.userData.handlers = {
    pointerenter: () => {
      hoverTl.play();
    },
    pointerleave: () => {
      hoverTl.reverse();
    },
    click: () => {
      ctx.emit('navigate', { to: 'hub-journal' });
    }
  };

  // --- Apply cinematic primitives ---
  const primitivesToApply = config.cinematicPrimitives || [];
  const cleanupFns = [];

  primitivesToApply.forEach((prim) => {
    if (ctx.primitives[prim.name]) {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result && result.cleanup) {
        cleanupFns.push(result.cleanup);
      }
    }
  });

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    hoverTl.kill();
    cleanupFns.forEach(fn => fn());
    bodyMat.dispose();
    capMat.dispose();
    rimMat.dispose();
    stripMat.dispose();
    shadowMat.dispose();
    bodyGeo.dispose();
    capGeo.dispose();
    rimGeo.dispose();
    stripGeo.dispose();
    shadowGeo.dispose();
  };

  return group;
}
